<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,onMounted,reactive,ref} from 'vue'
import {ArrowLeft,ClipboardList,Download,FileCheck2,LogOut,PanelRightClose,PanelRightOpen,ShieldCheck,X} from 'lucide-vue-next'
import ProfessionalReportPreview from '../prototypes/expert-review/ProfessionalReportPreview.vue'
import FreeReportPreview from '../prototypes/expert-review/FreeReportPreview.vue'
import RecordsPanel from './RecordsPanel.vue'
import RedactionEditor from './RedactionEditor.vue'
import {api,ApiError,setCsrf,type User,type Review,type Note,type CaseDetail,type CaseItem} from './api'

const user=ref<User>(),initializing=ref(true),busy=ref(false),error=ref(''),feedback=ref(''),login=reactive({username:'',password:''})
const screen=ref<'cases'|'knowledge'>('cases'),items=ref<CaseItem[]>([]),total=ref(0),page=ref(1),search=ref('')
const detail=ref<CaseDetail>(),review=ref<Review>(),sourceVisible=ref(true),railVisible=ref(true),activeModule=ref(''),selectedTarget=ref(''),dirty=ref(false)
const knowledge=ref<any[]>([]),knowledgeTotal=ref(0),knowledgePage=ref(1),knowledgeStatus=ref('all'),generationContext=ref<any>()
const directFeedback=ref(false)
const knowledgeHint=computed(()=>directFeedback.value?'勾选的医学知识在专家提交后直接入库，后续新报告按条件引用；历史报告不变。':'知识候选进入待专人确认区，未确认不参与生成；历史报告不变。')
const knowledgeChoice=computed(()=>directFeedback.value?'沉淀为可复用知识（提交后反哺方案生成）':'建议沉淀为可复用知识（待专人确认）')
const freeRenderer=ref<InstanceType<typeof FreeReportPreview>>(),reportContainer=ref<HTMLElement>(),rail=ref<HTMLElement>(),curating=ref<number>(),submitDialog=ref(false),attest=ref(false)
const blank=():Omit<Note,'id'|'module'>=>({target:'',decision:'认可',text:'',replacement:'',evidence:'',evidenceFiles:[],knowledge:{candidate:false,title:'',applicability:'',exclusions:'',keywords:[],requiredTerms:[],excludedTerms:[]}})
const form=reactive(blank()),terms=reactive({keywords:'',required:'',excluded:''})
const pendingNoteId=ref<string>()
const modules=computed(()=>detail.value?.modules||[]),current=computed(()=>modules.value.find(m=>m.key===activeModule.value)),notes=computed(()=>review.value?.notes.filter(n=>n.module===activeModule.value)||[]),readOnly=computed(()=>review.value?.status==='submitted'||user.value?.role==='data_curator'),progress=computed(()=>review.value?.confirmed.length||0)
const selectedLabel=computed(()=>current.value?.targets.find(t=>t.id===selectedTarget.value)?.label||current.value?.label||'整个模块')
const sourceInfo=computed(()=>detail.value?.input.sourceInfo||{})
const canCurate=computed(()=>['admin','data_curator'].includes(user.value?.role||''))
const canReview=computed(()=>['expert','admin'].includes(user.value?.role||''))
const split=(v:string)=>v.split(/[,，\n]/).map(s=>s.trim()).filter(Boolean)
function clearForm(){Object.assign(form,blank());selectedTarget.value=activeModule.value;pendingNoteId.value=undefined;terms.keywords='';terms.required='';terms.excluded=''}
function restore(){clearForm();const d=review.value?.drafts[activeModule.value];if(d){Object.assign(form,JSON.parse(JSON.stringify(d)));selectedTarget.value=d.target;terms.keywords=d.knowledge.keywords.join('，');terms.required=d.knowledge.requiredTerms.join('，');terms.excluded=d.knowledge.excludedTerms.join('，')}}
function edit(){dirty.value=true;feedback.value=''}
function draft(){form.target=selectedTarget.value||activeModule.value;form.knowledge.keywords=split(terms.keywords);form.knowledge.requiredTerms=split(terms.required);form.knowledge.excludedTerms=split(terms.excluded);return JSON.parse(JSON.stringify(form)) as Omit<Note,'id'|'module'>}
function handleError(e:unknown){error.value=e instanceof Error?e.message:'操作失败。';if(e instanceof ApiError&&e.status===401){user.value=undefined;detail.value=undefined;review.value=undefined;setCsrf('')}}
async function run(task:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';feedback.value='';try{await task()}catch(e){handleError(e)}finally{busy.value=false}}
async function loadCases(){const r=await api(`/cases?page=${page.value}&search=${encodeURIComponent(search.value)}`);items.value=r.items;total.value=r.total}
async function loadKnowledge(){const r=await api(`/knowledge?page=${knowledgePage.value}&status=${knowledgeStatus.value}`);knowledge.value=r.items;knowledgeTotal.value=r.total;directFeedback.value=r.knowledgePolicy?.directFeedbackEnabled===true}
async function signIn(){await run(async()=>{const r=await api('/session','POST',login);user.value=r.user;setCsrf(r.csrf);directFeedback.value=r.knowledgePolicy?.directFeedbackEnabled===true;login.password='';await loadCases()})}
async function withdrawKnowledge(id:string){if(!window.confirm('撤回后，此知识不再参与后续方案生成。确定撤回？'))return;await run(async()=>{await api(`/knowledge/${id}/withdraw`,'POST',{});await loadKnowledge();feedback.value='已撤回，后续方案生成不再检索此知识。'})}
async function persist(){if(!review.value||readOnly.value)return;const r=await api(`/reviews/${review.value.id}`,'PUT',{version:review.value.version,notes:review.value.notes,confirmed:review.value.confirmed,drafts:review.value.drafts});review.value=r.review;dirty.value=false}
async function stash(){if(!dirty.value||!review.value||readOnly.value)return;review.value.drafts[activeModule.value]=draft();review.value.confirmed=review.value.confirmed.filter(k=>k!==activeModule.value);await persist()}
async function signOut(){await run(async()=>{await stash();await api('/session','DELETE');user.value=undefined;detail.value=undefined;review.value=undefined;items.value=[];knowledge.value=[];setCsrf('');history.replaceState(null,'',location.pathname)})}
async function openCase(item:Pick<CaseItem,'mode'|'id'>){await run(async()=>{await stash();const r=await api(`/cases/${item.mode}/${item.id}`);detail.value=r.case;review.value=r.review||undefined;generationContext.value=r.generationContext;activeModule.value=r.case.modules[0].key;restore();sourceVisible.value=true;dirty.value=false;history.replaceState(null,'',`${location.pathname}?mode=${item.mode}&case=${encodeURIComponent(item.id)}`);window.scrollTo({top:0,behavior:'instant'})})}
async function back(){await run(async()=>{await stash();detail.value=undefined;review.value=undefined;history.replaceState(null,'',location.pathname);await loadCases()})}
async function navigate(value:'cases'|'knowledge'){await run(async()=>{await stash();detail.value=undefined;review.value=undefined;screen.value=value;history.replaceState(null,'',`${location.pathname}${value==='knowledge'?'?screen=knowledge':''}`);if(value==='cases')await loadCases();else await loadKnowledge()})}
async function selectModule(key:string,scroll=true){await run(async()=>{await stash();activeModule.value=key;restore();const q=new URLSearchParams(location.search);q.set('module',key);history.replaceState(null,'',`${location.pathname}?${q}`);if(detail.value?.mode==='free')freeRenderer.value?.showModule(key);await nextTick();if(scroll){const target=Array.from(reportContainer.value?.querySelectorAll<HTMLElement>('[data-review-module]')||[]).find(el=>el.dataset.reviewModule===key);target?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'})}})}
function pickTarget(event:MouseEvent|KeyboardEvent){if(readOnly.value||busy.value)return;const element=(event.target as HTMLElement).closest<HTMLElement>('[data-review-target]');if(!element)return;const moduleKey=element.dataset.reviewModule||activeModule.value,target=element.dataset.reviewTarget||moduleKey;if(dirty.value){feedback.value='请先保存当前批改，再更换对象。';return}if(moduleKey!==activeModule.value){activeModule.value=moduleKey;restore()}if(current.value?.targets.some(t=>t.id===target))selectedTarget.value=target;const q=new URLSearchParams(location.search);q.set('module',activeModule.value);history.replaceState(null,'',`${location.pathname}?${q}`)}
function validate(){if(form.decision!=='认可'&&!form.text.trim())throw Error('请填写批改原因。');if(['修改','补充'].includes(form.decision)&&!form.replacement.trim())throw Error('请填写建议文案。');if(form.knowledge.candidate&&(!form.evidence.trim()||!form.knowledge.title.trim()||!form.knowledge.applicability.trim()||!form.knowledge.exclusions.trim()))throw Error('知识候选请填写标题、依据、适用及不适用条件。')}
async function addNote(){if(!review.value||readOnly.value)return;validate();pendingNoteId.value||=crypto.randomUUID();review.value.notes=review.value.notes.filter(n=>n.id!==pendingNoteId.value);review.value.notes.push({id:pendingNoteId.value,module:activeModule.value,...draft()});review.value.confirmed=review.value.confirmed.filter(k=>k!==activeModule.value);delete review.value.drafts[activeModule.value];dirty.value=true;await persist();clearForm()}
async function saveNote(){await run(async()=>{await addNote();feedback.value='审阅记录已保存到服务器。'})}
async function saveDraft(){await run(async()=>{await stash();feedback.value='草稿已保存到服务器。'})}
async function confirmModule(){await run(async()=>{if(!review.value||readOnly.value)return;if(dirty.value||!notes.value.length)await addNote();if(!review.value.confirmed.includes(activeModule.value))review.value.confirmed.push(activeModule.value);delete review.value.drafts[activeModule.value];dirty.value=true;await persist();feedback.value=`已确认：${current.value?.label}`})}
async function deleteNote(id:string){await run(async()=>{if(!review.value||readOnly.value)return;review.value.notes=review.value.notes.filter(n=>n.id!==id);review.value.confirmed=review.value.confirmed.filter(k=>k!==activeModule.value);dirty.value=true;await persist()})}
async function submit(){await run(async()=>{await stash();if(!review.value)return;const r=await api(`/reviews/${review.value.id}/submit`,'POST',{version:review.value.version,attest:attest.value});review.value=r.review;submitDialog.value=false;feedback.value=`审阅已提交并锁定。${knowledgeHint.value}`})}
async function openCuration(index:number){await run(async()=>{await stash();curating.value=index})}
async function published(){curating.value=undefined;if(detail.value)await openCase({mode:detail.value.mode,id:detail.value.sourceId})}
function exportReview(){if(!review.value||!detail.value)return;const url=URL.createObjectURL(new Blob([JSON.stringify({report:detail.value.submissionNo,sourceFingerprint:detail.value.fingerprint,reviewer:user.value?.username,review:review.value},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`review-${detail.value.submissionNo}.json`;a.click();URL.revokeObjectURL(url)}
async function showRail(){railVisible.value=true;await nextTick();rail.value?.scrollIntoView({behavior:'smooth',block:'start'})}
const stateLabel=(state:string)=>({draft:'审阅草稿',submitted:'已提交',unreviewed:'待审阅',pending_confirmation:'待专人确认',expert_published:'专家已发布',approved:'专人已确认发布',rejected:'未通过',withdrawn:'已撤回'} as Record<string,string>)[state]||state
const date=(value:string)=>new Date(value).toLocaleString('zh-CN')
const knowledgeModules:Record<string,string>={records:'病历资料解读',pathology:'病理诊断与指标',assessment:'病情综合评估',treatment:'治疗路径',cost:'费用预算',advanced:'前沿技术药物',comparison:'国家地区就医对比',itinerary:'行程与停留时间',similarCases:'相似病例',topDoctors:'专家选择',service:'医疗服务和支付保险',risk:'风险预后',hospitals:'医院选择',next:'下一步就诊流程'}
const matchingReason=(reason:string)=>({same_disease:'疾病匹配',semantic_relevance_passed:'语义相关性通过',clinical_conditions_passed:'医学条件检查通过',medical_applicability_evidence_verified:'适用性与病例原文证据核验通过'} as Record<string,string>)[reason]||(reason.startsWith('module:')?`对应模块：${knowledgeModules[reason.slice(7)]||reason.slice(7)}`:reason.startsWith('keyword_hits:')?`关键词命中 ${reason.slice(13)} 项`:reason)
function beforeUnload(event:BeforeUnloadEvent){if(dirty.value){event.preventDefault();event.returnValue=''}}
onMounted(async()=>{window.addEventListener('beforeunload',beforeUnload);try{const r=await api('/session');user.value=r.user;setCsrf(r.csrf);directFeedback.value=r.knowledgePolicy?.directFeedbackEnabled===true;const q=new URLSearchParams(location.search);if(q.get('case')&&['free','professional'].includes(q.get('mode')||'')){const loaded=await api(`/cases/${q.get('mode')}/${q.get('case')}`);detail.value=loaded.case;review.value=loaded.review||undefined;generationContext.value=loaded.generationContext;activeModule.value=loaded.case.modules.some((m:any)=>m.key===q.get('module'))?q.get('module')!:loaded.case.modules[0].key;restore();sourceVisible.value=true;dirty.value=false;await nextTick();if(detail.value?.mode==='free')freeRenderer.value?.showModule(activeModule.value)}else if(q.get('screen')==='knowledge'){screen.value='knowledge';await loadKnowledge()}else await loadCases()}catch(e){if(!(e instanceof ApiError&&e.status===401))handleError(e)}finally{initializing.value=false}})
onBeforeUnmount(()=>window.removeEventListener('beforeunload',beforeUnload))
</script>

<template>
 <div class="expert-app">
  <div v-if="initializing" class="workbench-loading" role="status">正在连接审阅服务…</div>
  <main v-else-if="!user" class="workbench-login"><FileCheck2 :size="35"/><h1>专家审阅工作台</h1><p>仅限后台开通的专家账号登录</p><form @submit.prevent="signIn"><label class="wb-label" for="username">账号</label><input id="username" v-model="login.username" class="wb-field" autocomplete="username" required/><label class="wb-label" for="password">密码</label><input id="password" v-model="login.password" class="wb-field" type="password" autocomplete="current-password" required/><p v-if="error" class="workbench-error" role="alert">{{error}}</p><button class="wb-button wb-primary" :disabled="busy">{{busy?'登录中…':'登录'}}</button></form></main>
  <template v-else>
   <header class="workbench-top"><div class="workbench-brand"><FileCheck2 :size="26"/><div><strong>专家审阅工作台</strong><small>{{user.displayName}} · {{canReview?'所有病例可审阅':'资料脱敏处理'}}</small></div></div><nav class="workbench-actions" aria-label="工作台导航"><button class="wb-button" :disabled="busy" :class="{'wb-selected':screen==='cases'}" @click="navigate('cases')">病例报告</button><button class="wb-button" :disabled="busy" :class="{'wb-selected':screen==='knowledge'}" @click="navigate('knowledge')">知识沉淀</button><button class="wb-button" :disabled="busy" @click="signOut"><LogOut :size="15"/>退出</button></nav></header>
   <div v-if="user.testAccount" class="test-warning">测试账号正在使用业务数据。正式推广前必须更换测试密码。</div>
   <p v-if="error" class="workbench-error global-feedback" role="alert">{{error}}</p><p v-if="feedback" class="review-feedback global-feedback" role="status">{{feedback}}</p>
   <main v-if="screen==='knowledge'" class="case-list">
    <div class="case-list-heading"><h1>知识沉淀</h1><p>{{directFeedback?'专家审阅提交 → 发布入库 → 新方案按条件检索':'专家建议 → 待专人确认 → 发布入库 → 按条件检索'}}</p></div>
    <p class="demo-notice"><ShieldCheck :size="20"/>{{knowledgeHint}} 专人确认属于后续功能，当前未开放。</p>
    <div class="case-filters"><label for="knowledge-status">状态</label><select id="knowledge-status" v-model="knowledgeStatus" class="wb-field" :disabled="busy" @change="knowledgePage=1;run(loadKnowledge)"><option value="all">全部</option><option value="expert_published">专家已发布</option><option value="pending_confirmation">待专人确认</option><option value="approved">专人已确认发布</option><option value="rejected">未通过</option><option value="withdrawn">已撤回</option></select><span>共 {{knowledgeTotal}} 条</span></div>
    <p v-if="!knowledge.length" class="empty-list">暂无知识条目。{{knowledgeHint}}</p>
    <article v-for="k in knowledge" :key="k.id" class="knowledge-card"><header><h2>{{k.title}}</h2><span>{{stateLabel(k.status)}} · v{{k.version}}</span></header><p>{{k.guidance}}</p><dl><dt>医学依据</dt><dd>{{k.evidence}}</dd><dt>适用条件</dt><dd>{{k.applicability}}</dd><dt>不适用条件</dt><dd>{{k.exclusions}}</dd></dl><small>来源：{{k.submission_no}} · 模块 {{k.module_key}} · {{k.expert_name}} · {{date(k.created_at)}}</small><button v-if="k.status!=='withdrawn'&&(user.role==='admin'||k.expert_id===user.id)" class="wb-button" :disabled="busy" @click="withdrawKnowledge(k.id)">撤回知识</button></article>
    <div class="records-pagination"><button class="wb-button" :disabled="busy||knowledgePage<=1" @click="knowledgePage--;run(loadKnowledge)">上一页</button><span>第 {{knowledgePage}} 页</span><button class="wb-button" :disabled="busy||knowledgePage*30>=knowledgeTotal" @click="knowledgePage++;run(loadKnowledge)">下一页</button></div>
   </main>
   <main v-else-if="!detail" class="case-list"><div class="case-list-heading"><h1>病例报告</h1><p>正式数据库 · 原始报告只读 · 身份脱敏 · 审阅独立保存</p></div><form class="case-filters" @submit.prevent="page=1;run(loadCases)"><input v-model="search" class="wb-field" placeholder="按报告编号或科室搜索" aria-label="搜索病例" maxlength="80"/><button class="wb-button" :disabled="busy">搜索</button><span>共 {{total}} 份报告</span></form><p v-if="!items.length" class="empty-list">暂无已生成的报告。</p><article v-for="item in items" :key="`${item.mode}-${item.id}`" class="case-card"><div><div class="case-title"><span>{{item.mode==='professional'?'专业报告':'可行性报告'}}</span><strong>{{item.submissionNo}}</strong></div><p>{{item.visitPurpose}} · {{item.gender==='female'?'女':item.gender==='male'?'男':'其他'}} · {{item.nationality||'国籍未填写'}}</p><small>{{date(item.createdAt)}} · {{item.uploadCount}} 份资料 · {{stateLabel(item.reviewStatus)}}</small></div><button class="wb-button wb-primary" :disabled="busy" @click="openCase(item)">{{canReview?'打开审阅':'处理资料'}}</button></article><div class="records-pagination"><button class="wb-button" :disabled="busy||page<=1" @click="page--;run(loadCases)">上一页</button><span>第 {{page}} 页</span><button class="wb-button" :disabled="busy||page*20>=total" @click="page++;run(loadCases)">下一页</button></div></main>
   <main v-else class="review-workspace">
    <div class="report-workbar"><div><strong>{{detail.submissionNo}} · {{detail.mode==='professional'?'专业报告':'可行性报告'}}</strong><small>只读原稿 · 版本 {{detail.fingerprint.slice(0,12)}} · {{dirty?'有未保存内容':'服务器草稿'}}</small></div><div class="workbench-actions"><button class="wb-button" :disabled="busy" @click="back"><ArrowLeft :size="15"/>病例列表</button><button class="wb-button" :aria-expanded="sourceVisible" @click="sourceVisible=!sourceVisible"><ClipboardList :size="16"/>用户提交资料</button><button v-if="canReview" class="wb-button rail-toggle" @click="railVisible=!railVisible"><component :is="railVisible?PanelRightClose:PanelRightOpen" :size="17"/>{{railVisible?'收起审阅栏':'打开审阅栏'}}</button></div></div>
    <details v-if="generationContext?.citations?.length" class="demo-notice knowledge-trace"><summary>本报告生成时提供过 {{generationContext.citations.length}} 条专家知识参考（不代表模型已采纳）</summary><ul><li v-for="c in generationContext.citations" :key="c.id"><strong>{{c.title}} · v{{c.version}}</strong><span v-if="c.module">模块：{{knowledgeModules[c.module]||c.module}}</span><span v-if="c.match">检索相关分：{{c.match.score}} · 语义相似度：{{c.match.semantic}}（不是医学置信概率）</span><small v-if="c.match?.reasons">匹配依据：{{c.match.reasons.map(matchingReason).join(' · ')}}</small><small v-if="c.match?.applicability?.evidenceQuotes?.length">适用性核验的病例原文：{{c.match.applicability.evidenceQuotes.join('；')}}</small></li></ul></details>
    <p v-else-if="generationContext?.retrieval?.algorithm" class="demo-notice">本报告未提供专家知识参考。{{['semantic_unavailable','applicability_unavailable','corpus_limit_requires_index_upgrade','clinical_profile_requires_compaction'].includes(generationContext.retrieval.outcome)?'匹配或适用性核验未通过运行条件检查；未使用不确定知识兜底。':'当前没有满足相关性与适用条件的知识，或本次生成未用到对应模块。'}}</p>
    <RecordsPanel :source="detail.input" :case-id="detail.id" :open="sourceVisible" :can-curate="canCurate" @toggle="sourceVisible=!sourceVisible" @curate="openCuration"/>
    <div :class="['report-review-layout',{'without-rail':!railVisible||!canReview}]"><div ref="reportContainer" class="formal-report-host" @click="pickTarget" @keydown.enter="pickTarget"><ProfessionalReportPreview v-if="detail.mode==='professional'" :key="detail.id" :report="detail.report" :active-key="activeModule" @module="selectModule($event,false)"/><FreeReportPreview v-else ref="freeRenderer" :key="detail.id" :report="detail.report" :source-info="sourceInfo" @back="back" @open-pro="feedback='请从病例列表选择对应专业报告，不会生成新报告。'"/></div>
     <aside v-if="canReview&&railVisible&&review" ref="rail" class="review-rail" aria-label="专家审阅栏"><div class="rail-heading"><div><h2>专家审阅</h2><small>原稿不改动，审阅与知识建议分开保存</small></div><button class="wb-icon" aria-label="收起审阅栏" @click="railVisible=false"><X :size="18"/></button></div><div class="review-progress"><span>模块确认 {{progress}} / {{modules.length}}</span><span>{{stateLabel(review.status)}}</span><progress :value="progress" :max="modules.length"/></div>
      <label class="wb-label" for="module">当前审阅模块</label><select id="module" class="wb-field" :value="activeModule" :disabled="busy" @change="selectModule(($event.target as HTMLSelectElement).value)"><option v-for="m in modules" :key="m.key" :value="m.key">{{review.confirmed.includes(m.key)?'✓ ':''}}{{m.label}}</option></select><div class="target-box"><small>审阅对象</small><strong>{{selectedLabel}}</strong><span>点击报告内容块可针对该块批改。</span></div>
      <form @submit.prevent="saveNote"><fieldset :disabled="busy||readOnly"><legend class="wb-label">审阅结论</legend><div class="decision-grid"><label v-for="choice in ['认可','修改','批注','补充','依据不足','不适用']" :key="choice" :class="{selected:form.decision===choice}"><input v-model="form.decision" type="radio" name="decision" :value="choice" @change="edit"/>{{choice}}</label></div><label class="wb-label" for="note">{{form.decision==='认可'?'备注（可选）':'批改原因'}}</label><textarea id="note" v-model="form.text" class="wb-field" rows="3" @input="edit"/>
      <template v-if="['修改','补充'].includes(form.decision)"><label class="wb-label" for="replacement">建议文案（不覆盖原稿）</label><textarea id="replacement" v-model="form.replacement" class="wb-field" rows="4" @input="edit"/></template><label class="wb-label" for="evidence">医学依据 / 来源</label><textarea id="evidence" v-model="form.evidence" class="wb-field" rows="2" @input="edit"/><div v-if="detail.input.uploads.length" class="evidence-files"><span class="wb-label">引用的病历资料</span><label v-for="f in detail.input.uploads" :key="f.index"><input v-model="form.evidenceFiles" type="checkbox" :value="f.index" @change="edit"/>{{f.name}}</label></div>
      <div v-if="['修改','补充'].includes(form.decision)&&!['overview','sample','packages','upgrade','fallback-8','fallback-13','fallback-14'].includes(activeModule)" class="knowledge-editor"><label class="attestation"><input v-model="form.knowledge.candidate" type="checkbox" @change="edit"/>{{knowledgeChoice}}</label><template v-if="form.knowledge.candidate"><label class="wb-label">知识标题<input v-model="form.knowledge.title" class="wb-field" maxlength="160" @input="edit"/></label><label class="wb-label">适用条件<textarea v-model="form.knowledge.applicability" class="wb-field" rows="2" @input="edit"/></label><label class="wb-label">不适用条件<textarea v-model="form.knowledge.exclusions" class="wb-field" rows="2" @input="edit"/></label><label class="wb-label">检索关键词（逗号分隔）<input v-model="terms.keywords" class="wb-field" @input="edit"/></label><label class="wb-label">必须同时出现的条件词<input v-model="terms.required" class="wb-field" @input="edit"/></label><label class="wb-label">排除条件词<input v-model="terms.excluded" class="wb-field" @input="edit"/></label><small>写通用医学建议，不要复制患者身份或把单一病例当成普遍结论。</small></template></div>
      <div class="rail-buttons"><button type="submit" class="wb-button">保存记录</button><button type="button" class="wb-button wb-primary" @click="confirmModule">确认本模块</button></div><button type="button" class="wb-button draft-button" :disabled="!dirty" @click="saveDraft">保存当前草稿</button></fieldset></form>
      <div class="module-notes"><h3>本模块记录 {{notes.length}}</h3><p v-if="!notes.length" class="empty-note">暂无记录</p><article v-for="n in notes" :key="n.id" class="review-note"><div><strong>{{n.decision}}{{n.knowledge.candidate?' · 知识候选':''}}</strong><button v-if="!readOnly" class="wb-icon" :disabled="busy" aria-label="删除此记录" @click="deleteNote(n.id)"><X :size="14"/></button></div><small>{{current?.targets.find(t=>t.id===n.target)?.label}}</small><p>{{n.text}}</p><p v-if="n.replacement" class="replacement">建议：{{n.replacement}}</p><p v-if="n.evidence">依据：{{n.evidence}}</p></article></div>
      <div class="submit-area"><button v-if="!readOnly" class="wb-button wb-primary" :disabled="busy" @click="submitDialog=true;attest=false">提交本报告审阅</button><span v-else>已提交并锁定 · {{date(review.submitted_at!)}}</span><button class="wb-button" :disabled="busy" @click="exportReview"><Download :size="14"/>导出审阅记录</button><small>提交前必须确认全部模块、查看全部脱敏原件。{{knowledgeHint}}</small></div>
     </aside>
    </div><button v-if="canReview" class="mobile-review-button wb-button wb-primary" @click="showRail">前往审阅栏</button>
   </main>
   <div v-if="submitDialog" class="modal-backdrop" @click.self="!busy&&(submitDialog=false)"><section role="dialog" aria-modal="true" aria-labelledby="submit-title" class="submit-dialog"><h2 id="submit-title">提交审阅</h2><p>已确认 {{progress}} / {{modules.length}} 个模块。提交后不能改动。</p><p>{{knowledgeHint}}</p><label class="attestation"><input v-model="attest" type="checkbox"/>我已核对用户输入、全部病历资料和报告，确认本次审阅记录。</label><div class="rail-buttons"><button class="wb-button" :disabled="busy" @click="submitDialog=false">返回审阅</button><button class="wb-button wb-primary" :disabled="busy||!attest||progress!==modules.length" @click="submit">确认提交</button></div></section></div>
   <RedactionEditor v-if="curating!==undefined&&detail" :case-id="detail.id" :index="curating" @close="curating=undefined" @published="published"/>
  </template>
 </div>
</template>
